import java.util.*;

public class MailForwarding {
    static class Mail implements Comparable<Mail> {
        int id;
        int source;
        int dest;
        int arrivalTime;
        int currentPos;
        int currentTime;

        Mail(int id, int source, int dest, int arrivalTime) {
            this.id = id;
            this.source = source;
            this.dest = dest;
            this.arrivalTime = arrivalTime;
            this.currentPos = source;
            this.currentTime = arrivalTime;
        }

        @Override
        public int compareTo(Mail other) {
            // For priority queue: oldest mail first (earliest arrival time)
            if (this.currentTime != other.currentTime) {
                return Integer.compare(this.currentTime, other.currentTime);
            }
            return Integer.compare(this.id, other.id);
        }
    }

    static class Event implements Comparable<Event> {
        int time;
        int postOffice;
        Mail mail;

        Event(int time, int postOffice, Mail mail) {
            this.time = time;
            this.postOffice = postOffice;
            this.mail = mail;
        }

        @Override
        public int compareTo(Event other) {
            if (this.time != other.time) {
                return Integer.compare(this.time, other.time);
            }
            if (this.postOffice != other.postOffice) {
                return Integer.compare(this.postOffice, other.postOffice);
            }
            return Integer.compare(this.mail.id, other.mail.id);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();

        // Build graph: adjacency list with (neighbor, edge weight)
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            graph.get(u).add(new int[]{v, w});
            graph.get(v).add(new int[]{u, w});
        }

        // Precompute shortest paths from each node using Dijkstra
        // dist[i][j] = shortest distance from i to j
        int[][] dist = new int[N + 1][N + 1];
        int[][] nextHop = new int[N + 1][N + 1]; // next hop from i to j

        for (int src = 1; src <= N; src++) {
            dijkstra(src, N, graph, dist[src], nextHop[src]);
        }

        int K = sc.nextInt();
        List<Mail> mails = new ArrayList<>();
        for (int i = 0; i < K; i++) {
            int s = sc.nextInt();
            int d = sc.nextInt();
            int t = sc.nextInt();
            mails.add(new Mail(i, s, d, t));
        }

        // Process events
        PriorityQueue<Event> events = new PriorityQueue<>();
        // carrierStatus[office] = time when carrier becomes available (0 = always available initially)
        int[] carrierAvailable = new int[N + 1];

        // Initialize: put all mails at their source at arrival time
        for (Mail mail : mails) {
            if (mail.source == mail.dest) {
                // Already at destination
                System.out.println(mail.arrivalTime);
                continue;
            }
            events.add(new Event(mail.arrivalTime, mail.source, mail));
        }

        int[] deliveryTime = new int[K];
        Arrays.fill(deliveryTime, -1);

        while (!events.isEmpty()) {
            Event ev = events.poll();
            int time = ev.time;
            int office = ev.postOffice;
            Mail mail = ev.mail;

            if (deliveryTime[mail.id] != -1) {
                continue; // already delivered
            }

            // Check if carrier is available at this time at this office
            if (carrierAvailable[office] > time) {
                // Carrier not available yet, reschedule
                events.add(new Event(carrierAvailable[office], office, mail));
                continue;
            }

            // Carrier is available now
            // Determine next hop
            int next = nextHop[office][mail.dest];
            if (next == -1) {
                // No path to destination (should not happen in valid input)
                continue;
            }

            // Find edge weight between office and next
            int travelTime = 0;
            for (int[] edge : graph.get(office)) {
                if (edge[0] == next) {
                    travelTime = edge[1];
                    break;
                }
            }

            // Carrier will be busy until time + travelTime
            carrierAvailable[office] = time + travelTime;

            if (next == mail.dest) {
                // Delivered
                deliveryTime[mail.id] = time + travelTime;
            } else {
                // Forward to next office
                events.add(new Event(time + travelTime, next, mail));
            }
        }

        // Output results
        for (int i = 0; i < K; i++) {
            System.out.println(deliveryTime[i]);
        }
    }

    static void dijkstra(int src, int N, List<List<int[]>> graph, int[] dist, int[] nextHop) {
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(nextHop, -1);
        dist[src] = 0;

        // Priority queue: (distance, node)
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.add(new int[]{0, src});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0];
            int u = cur[1];

            if (d != dist[u]) continue;

            for (int[] edge : graph.get(u)) {
                int v = edge[0];
                int w = edge[1];
                int nd = d + w;

                if (nd < dist[v]) {
                    dist[v] = nd;
                    nextHop[v] = u; // store predecessor
                    pq.add(new int[]{nd, v});
                } else if (nd == dist[v] && u < nextHop[v]) {
                    // Tie-breaking: prefer lower numbered predecessor
                    nextHop[v] = u;
                }
            }
        }

        // Convert predecessor to next hop from src
        // For each node, we want the first step from src to that node
        // We can reconstruct by following predecessor chain from node back to src
        for (int node = 1; node <= N; node++) {
            if (node == src) {
                nextHop[node] = node;
                continue;
            }
            if (nextHop[node] == -1) continue;

            // Reconstruct path from src to node
            int cur = node;
            while (nextHop[cur] != src && nextHop[cur] != -1) {
                cur = nextHop[cur];
            }
            if (nextHop[cur] == src) {
                nextHop[node] = cur; // first step from src is cur
            }
        }
        nextHop[src] = src; // self-loop for source
    }
}

