public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        int[][] adj = new int[N+1][N+1];
        for(int[] r : adj) Arrays.fill(r, Integer.MAX_VALUE/2);
        List<int[]>[] graph = new List[N+1];
        for(int i=1;i<=N;i++) { graph[i]=new ArrayList<>(); adj[i][i]=0; }
        for(int i=0;i<M;i++){
            int u=sc.nextInt(),v=sc.nextInt(),w=sc.nextInt();
            graph[u].add(new int[]{v,w}); graph[v].add(new int[]{u,w});
            adj[u][v]=Math.min(adj[u][v],w); adj[v][u]=Math.min(adj[v][u],w);
        }
        // For each destination, compute next hop using Dijkstra
        int[][] nextHop = new int[N+1][N+1];
        for(int dst=1;dst<=N;dst++){
            int[] dist=new int[N+1]; Arrays.fill(dist,Integer.MAX_VALUE/2); dist[dst]=0;
            PriorityQueue<int[]> pq=new PriorityQueue<>(Comparator.comparingInt((int[]x)->x[0]).thenComparingInt(x->x[1]));
            pq.offer(new int[]{0,dst});
            while(!pq.isEmpty()){int[]cur=pq.poll();int d=cur[0],u=cur[1];if(d>dist[u])continue;for(int[]e:graph[u]){int v=e[0],w=e[1];if(dist[u]+w<dist[v]){dist[v]=dist[u]+w;pq.offer(new int[]{dist[v],v});}}}
            for(int src=1;src<=N;src++){
                if(src==dst){nextHop[src][dst]=dst;continue;}
                int best=-1,bd=Integer.MAX_VALUE/2;
                for(int[]e:graph[src]){int v=e[0],w=e[1];if(dist[v]+w==dist[src]&&(best==-1||v<best)){best=v;bd=dist[v]+w;}}
                nextHop[src][dst]=best;
            }
        }
        int Q=sc.nextInt();
        long[] carrierFree=new long[N+1];
        PriorityQueue<long[]>[] queues=new PriorityQueue[N+1];
        for(int i=1;i<=N;i++) queues[i]=new PriorityQueue<>(Comparator.comparingLong((long[]x)->x[0]).thenComparingLong(x->x[1]));
        // events: {time, office, mailId, dst, arrivalAtOrigin}
        PriorityQueue<long[]> events=new PriorityQueue<>(Comparator.comparingLong((long[]x)->x[0]).thenComparingLong(x->x[1]));
        long[] results=new long[Q];
        for(int i=0;i<Q;i++){int s=sc.nextInt(),d=sc.nextInt();long t=sc.nextLong();events.offer(new long[]{t,i,s,d,t});}
        while(!events.isEmpty()){
            long[]ev=events.poll();long time=ev[0];int id=(int)ev[1],office=(int)ev[2],dst=(int)ev[3];long orig=ev[4];
            if(office==dst){results[id]=time;continue;}
            queues[office].offer(new long[]{orig,id,dst});
            if(carrierFree[office]<=time){
                long[]mail=queues[office].poll();
                long otime=mail[0];int mid=(int)mail[1],mdst=(int)mail[2];
                int nh=nextHop[office][mdst];
                long arrive=time+adj[office][nh];
                carrierFree[office]=arrive;
                events.offer(new long[]{arrive,mid,nh,mdst,otime});
            }
        }
        // Need to handle carrier returning and processing queue
        // This simple approach misses queued items after carrier leaves
        for(int i=0;i<Q;i++) System.out.println(results[i]);
    }
}

import java.io.*;
import java.util.*;

/*
 * Postal Worker Rings Once
 *
 * We simulate mail forwarding in a graph.
 *
 * Rules:
 * - For each pair (u, v), mail follows a shortest path.
 * - If multiple shortest paths exist, choose the next office with the smallest number.
 * - Each office has one worker. A worker can only forward mail when present at that office.
 * - If absent when mail arrives, the mail waits.
 * - Workers always take the oldest waiting mail first.
 * - After delivering one mail to the next office, the worker immediately returns home.
 * - Travel time along an edge is its weight; a forwarding trip u->nxt->u takes 2*w time total,
 *   but the mail itself arrives at nxt after w time.
 *
 * Simulation strategy:
 * - Precompute next[u][v]: first hop from u toward v under the required routing rule.
 * - Maintain, for each office:
 *      * workerAvailable[u]: earliest time the worker is at home and can depart
 *      * waiting queue ordered by (arrivalTime, insertionOrder)
 * - Use an event queue with two event types:
 *      * MAIL_ARRIVE(office, mail)
 *      * WORKER_RETURN(office)
 * - At each event time, process all events of that time:
 *      1) worker returns
 *      2) mail arrivals
 *   Then repeatedly dispatch from any office that can now send.
 *
 * Dispatch:
 * - If worker is present and queue non-empty, pop oldest mail.
 * - If destination == current office, mark delivered immediately at current time.
 * - Else send to next hop; schedule mail arrival at currentTime + w and worker return at currentTime + 2*w.
 *
 * Input format assumed:
 * Multiple test cases.
 * For each case:
 *   n m
 *   m lines: a b t      (undirected roads)
 *   k
 *   k lines: startTime source dest
 * Terminates with: 0 0
 *
 * Output:
 * For each case:
 *   Simulation X
 *   i deliveryTime
 * for mail items in input order (1-based)
 *
 * This matches the classic UVa 10187/10246 style? If judge differs slightly in wording,
 * core algorithm remains the same.
 */
public class Main {
    static final long INF = (long) 4e18;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            long v = nextLong();
            if (v == Long.MIN_VALUE) return Integer.MIN_VALUE;
            return (int) v;
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Mail {
        int id;
        int dest;
        long arrivalTimeAtOffice;
        long order;
        Mail(int id, int dest, long arrivalTimeAtOffice, long order) {
            this.id = id;
            this.dest = dest;
            this.arrivalTimeAtOffice = arrivalTimeAtOffice;
            this.order = order;
        }
    }

    static class Event implements Comparable<Event> {
        static final int RETURN = 0;
        static final int ARRIVE = 1;

        long time;
        int type;
        int office;
        Mail mail; // only for ARRIVE

        Event(long time, int type, int office, Mail mail) {
            this.time = time;
            this.type = type;
            this.office = office;
            this.mail = mail;
        }

        public int compareTo(Event other) {
            if (time != other.time) return Long.compare(time, other.time);
            if (type != other.type) return Integer.compare(type, other.type); // RETURN before ARRIVE
            return Integer.compare(office, other.office);
        }
    }

    static class State implements Comparable<State> {
        long dist;
        int node;
        State(long dist, int node) {
            this.dist = dist;
            this.node = node;
        }
        public int compareTo(State o) {
            if (dist != o.dist) return Long.compare(dist, o.dist);
            return Integer.compare(node, o.node);
        }
    }

    static int n, m;
    static ArrayList<Edge>[] g;
    static long[][] dist;
    static int[][] nextHop;
    static long[][] weight;

    static void dijkstraAllPairs() {
        dist = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dist[i], INF);
            PriorityQueue<State> pq = new PriorityQueue<>();
            dist[i][i] = 0;
            pq.add(new State(0, i));
            while (!pq.isEmpty()) {
                State cur = pq.poll();
                if (cur.dist != dist[i][cur.node]) continue;
                for (Edge e : g[cur.node]) {
                    long nd = cur.dist + e.w;
                    if (nd < dist[i][e.to]) {
                        dist[i][e.to] = nd;
                        pq.add(new State(nd, e.to));
                    }
                }
            }
        }
    }

    static void buildNextHop() {
        nextHop = new int[n + 1][n + 1];
        weight = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(weight[i], INF);
            for (Edge e : g[i]) weight[i][e.to] = Math.min(weight[i][e.to], e.w);
        }

        for (int u = 1; u <= n; u++) {
            for (int v = 1; v <= n; v++) {
                if (u == v) {
                    nextHop[u][v] = u;
                    continue;
                }
                int best = -1;
                for (Edge e : g[u]) {
                    int x = e.to;
                    if (dist[u][v] == e.w + dist[x][v]) {
                        if (best == -1 || x < best) best = x;
                    }
                }
                nextHop[u][v] = best;
            }
        }
    }

    static void tryDispatch(int office,
                            long currentTime,
                            long[] workerAvailable,
                            PriorityQueue<Mail>[] waiting,
                            PriorityQueue<Event> events,
                            long[] delivered) {
        while (workerAvailable[office] <= currentTime && !waiting[office].isEmpty()) {
            Mail mail = waiting[office].poll();
            if (mail.dest == office) {
                delivered[mail.id] = currentTime;
                continue;
            }
            int nxt = nextHop[office][mail.dest];
            long w = weight[office][nxt];

            Mail forwarded = new Mail(mail.id, mail.dest, currentTime + w, mail.order);
            events.add(new Event(currentTime + w, Event.ARRIVE, nxt, forwarded));

            workerAvailable[office] = currentTime + 2L * w;
            events.add(new Event(workerAvailable[office], Event.RETURN, office, null));

            // worker left, cannot send more now
            break;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();
        int tc = 1;

        while (true) {
            int nn = fs.nextInt();
            int mm = fs.nextInt();
            if (nn == Integer.MIN_VALUE) break;
            if (nn == 0 && mm == 0) break;

            n = nn;
            m = mm;
            g = new ArrayList[n + 1];
            for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int a = fs.nextInt();
                int b = fs.nextInt();
                long t = fs.nextLong();
                g[a].add(new Edge(b, t));
                g[b].add(new Edge(a, t));
            }

            dijkstraAllPairs();
            buildNextHop();

            int k = fs.nextInt();
            long[] delivered = new long[k + 1];

            @SuppressWarnings("unchecked")
            PriorityQueue<Mail>[] waiting = new PriorityQueue[n + 1];
            for (int i = 1; i <= n; i++) {
                waiting[i] = new PriorityQueue<>((x, y) -> {
                    if (x.arrivalTimeAtOffice != y.arrivalTimeAtOffice)
                        return Long.compare(x.arrivalTimeAtOffice, y.arrivalTimeAtOffice);
                    return Long.compare(x.order, y.order);
                });
            }

            long[] workerAvailable = new long[n + 1];
            Arrays.fill(workerAvailable, 0L);

            PriorityQueue<Event> events = new PriorityQueue<>();
            long orderCounter = 0;

            for (int i = 1; i <= k; i++) {
                long startTime = fs.nextLong();
                int src = fs.nextInt();
                int dst = fs.nextInt();
                Mail mail = new Mail(i, dst, startTime, orderCounter++);
                events.add(new Event(startTime, Event.ARRIVE, src, mail));
            }

            while (!events.isEmpty()) {
                long t = events.peek().time;
                ArrayList<Event> batch = new ArrayList<>();
                while (!events.isEmpty() && events.peek().time == t) {
                    batch.add(events.poll());
                }

                boolean[] touched = new boolean[n + 1];

                // returns first
                for (Event e : batch) {
                    if (e.type == Event.RETURN) {
                        if (workerAvailable[e.office] < t) workerAvailable[e.office] = t;
                        touched[e.office] = true;
                    }
                }

                // arrivals next
                for (Event e : batch) {
                    if (e.type == Event.ARRIVE) {
                        waiting[e.office].add(e.mail);
                        touched[e.office] = true;
                    }
                }

                for (int office = 1; office <= n; office++) {
                    if (touched[office]) {
                        tryDispatch(office, t, workerAvailable, waiting, events, delivered);
                    }
                }
            }

            out.append("Simulation ").append(tc++).append('\n');
            for (int i = 1; i <= k; i++) {
                out.append(i).append(' ').append(delivered[i]).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXN 1000
#define MAXM 100000

typedef struct {
    int to, next;
} Edge;

Edge edges[MAXM];
int head[MAXN], edge_cnt;
int n, m, q;

typedef struct Mail {
    int id, src, dst, time;
    struct Mail *next;
} Mail;

Mail *mail_queue[MAXN]; // queue per node (linked list, sorted by arrival time)
int queue_size[MAXN];

int dist[MAXN][MAXN]; // shortest distances
int next_hop[MAXN][MAXN]; // next hop on shortest path (with tie-breaking)

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void bfs(int src) {
    int queue[MAXN], front = 0, rear = 0;
    int visited[MAXN];
    for (int i = 0; i < n; i++) {
        dist[src][i] = -1;
        visited[i] = 0;
    }
    dist[src][src] = 0;
    next_hop[src][src] = -1;
    queue[rear++] = src;
    visited[src] = 1;
    while (front < rear) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (!visited[v]) {
                visited[v] = 1;
                dist[src][v] = dist[src][u] + 1;
                if (u == src) {
                    next_hop[src][v] = v;
                } else {
                    next_hop[src][v] = next_hop[src][u];
                }
                queue[rear++] = v;
            }
        }
    }
}

void enqueue(int node, Mail *mail) {
    Mail **p = &mail_queue[node];
    while (*p != NULL && (*p)->time <= mail->time) {
        p = &(*p)->next;
    }
    mail->next = *p;
    *p = mail;
    queue_size[node]++;
}

Mail* dequeue(int node) {
    if (queue_size[node] == 0) return NULL;
    Mail *mail = mail_queue[node];
    mail_queue[node] = mail->next;
    queue_size[node]--;
    mail->next = NULL;
    return mail;
}

int main() {
    scanf("%d %d %d", &n, &m, &q);
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        add_edge(u, v);
        add_edge(v, u);
    }
    for (int i = 0; i < n; i++) {
        bfs(i);
    }
    // Tie-breaking: if two paths have same length, prefer lower next hop
    for (int s = 0; s < n; s++) {
        for (int t = 0; t < n; t++) {
            if (s == t) continue;
            if (dist[s][t] == -1) continue;
            // find minimal next hop among shortest paths
            int best_next = -1;
            int best_dist = dist[s][t];
            for (int e = head[s]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (dist[v][t] != -1 && 1 + dist[v][t] == best_dist) {
                    if (best_next == -1 || v < best_next) {
                        best_next = v;
                    }
                }
            }
            next_hop[s][t] = best_next;
        }
    }

    // Initialize mail queues
    for (int i = 0; i < n; i++) {
        mail_queue[i] = NULL;
        queue_size[i] = 0;
    }

    // Read mail items and enqueue at source
    Mail *all_mail = (Mail*)malloc(q * sizeof(Mail));
    for (int i = 0; i < q; i++) {
        int s, d, t;
        scanf("%d %d %d", &s, &d, &t);
        s--; d--;
        all_mail[i].id = i + 1;
        all_mail[i].src = s;
        all_mail[i].dst = d;
        all_mail[i].time = t;
        all_mail[i].next = NULL;
        enqueue(s, &all_mail[i]);
    }

    int delivered[q];
    int deliver_time[q];
    for (int i = 0; i < q; i++) {
        delivered[i] = 0;
    }

    int current_time = 0;
    int carrier_at[MAXN]; // -1 if idle, else mail id being carried
    for (int i = 0; i < n; i++) carrier_at[i] = -1;
    int carrier_ready_time[MAXN]; // when carrier becomes free
    for (int i = 0; i < n; i++) carrier_ready_time[i] = 0;

    // While there are undelivered mails
    int undelivered = q;
    while (undelivered > 0) {
        // Find earliest time when something happens:
        // either a carrier becomes free, or a mail arrives at a node (from queue)
        int next_time = INT_MAX;
        for (int i = 0; i < n; i++) {
            if (carrier_ready_time[i] > current_time) {
                if (carrier_ready_time[i] < next_time) next_time = carrier_ready_time[i];
            }
