static int cmp_event(const void *a, const void *b) {
    const Event *x = (const Event*)a;
    const Event *y = (const Event*)b;
    if (x->time != y->time) return x->time - y->time;
    if (x->type != y->type) return x->type - y->type; // arrivals before returns
    if (x->office != y->office) return x->office - y->office;
    return x->id - y->id;
}

static void try_send(int u, int current_time) {
    if (carrier_free[u] > current_time) return;
